<?= $this->extend('layout') ?><?= $this->section('content') ?><div class="card"><h1>Bank Soal: <?= esc($exam['title']) ?></h1><form method="post" action="/guru/exams/<?= (int)$exam['id'] ?>/questions"><?= csrf_field() ?><label>Tipe soal</label><select name="question_type" id="qt" onchange="document.getElementById('opts').style.display=this.value==='mcq'?'block':'none'"><option value="mcq">Pilihan ganda</option><option value="essay">Esai</option></select><label>Teks soal</label><textarea name="question_text" rows="3" required></textarea><div id="opts"><label>Opsi A</label><input name="option_a"><label>Opsi B</label><input name="option_b"><label>Opsi C</label><input name="option_c"><label>Opsi D</label><input name="option_d"><label>Kunci jawaban</label><select name="correct_option"><option>A</option><option>B</option><option>C</option><option>D</option></select></div><label>Poin</label><input type="number" name="points" min="1" value="1"><button class="btn green">Tambah Soal</button></form></div><div class="card"><h2>Soal tersimpan (<?= count($questions) ?>)</h2><ol><?php foreach($questions as $q): ?><li><?= esc($q['question_text']) ?> <span class="muted">(<?= esc($q['question_type']) ?> · <?= esc($q['points']) ?> poin)</span></li><?php endforeach ?></ol></div><?= $this->endSection() ?>